import hashlib, hmac, base64, json
KEY = b"demo-secret"
def b64(d):
    return base64.urlsafe_b64encode(d).rstrip(b"=").decode()
def make(payload):
    body = b64(json.dumps(payload, separators=(",", ":"), sort_keys=True).encode())
    sig = b64(hmac.new(KEY, body.encode(), hashlib.sha256).digest())
    return body + "." + sig
def verify_buggy(tok, now):
    body, sig = tok.rsplit(".", 1)
    expect = b64(hmac.new(KEY, body.encode(), hashlib.sha256).digest())
    return hmac.compare_digest(sig, expect)
def verify_fixed(tok, now):
    if not verify_buggy(tok, now):
        return False
    payload = json.loads(base64.urlsafe_b64decode(body_pad(tok)))
    return now < payload["exp"]
def body_pad(tok):
    body = tok.split(".")[0]
    return body + "=" * (-len(body) % 4)
